class Trie {
    // Each level is a map from char to the next level; '#' marks end of word
    static class CharMap extends HashMap<Character, CharMap> {}

    private final CharMap root = new CharMap();

    public Trie() {}

    public void insert(String word) {
        CharMap node = root;
        for (char ch : word.toCharArray()) {
            node = node.computeIfAbsent(ch, k -> new CharMap());
        }
        node.put('#', new CharMap());
    }

    public boolean search(String word) {
        CharMap node = root;
        for (char ch : word.toCharArray()) {
            if (!node.containsKey(ch)) return false;
            node = node.get(ch);
        }
        return node.containsKey('#');
    }

    public boolean startsWith(String prefix) {
        CharMap node = root;
        for (char ch : prefix.toCharArray()) {
            if (!node.containsKey(ch)) return false;
            node = node.get(ch);
        }
        return true;
    }
}

